// src/components/forms/florida-llc/validation.ts
function buildFinalLlcName(desired, designator) {
  const cleaned = desired.trim();
  if (!cleaned || !designator) return cleaned;
  const lower = cleaned.toLowerCase();
  const hasIt = lower.endsWith("llc") || lower.endsWith("l.l.c.") || lower.endsWith("limited liability company") || lower.endsWith("pllc") || lower.endsWith("p.l.l.c.") || lower.endsWith("professional limited liability company");
  if (hasIt) return cleaned;
  return `${cleaned}, ${designator}`;
}
function validateRegisteredAgentAddress(street1, street2, state) {
  if (state !== "FL") {
    return "Registered agent address must be a physical Florida street address.";
  }
  if (isPoBox(street1) || isPoBox(street2 ?? "")) {
    return "A P.O. Box cannot be used for the registered agent address.";
  }
  return null;
}
function calculateEstimatedFees(opts) {
  const articlesOfOrganization = opts.isConversion ? 0 : 100;
  const registeredAgentDesignation = 25;
  const certificateOfStatus = opts.certificateOfStatus ? 5 : 0;
  const certifiedCopy = opts.certifiedCopy ? 30 : 0;
  const extraSeries = Math.max(0, (opts.seriesCount ?? 0) - 3);
  const additionalSeriesFee = extraSeries * 50;
  return {
    articlesOfOrganization,
    registeredAgentDesignation,
    certificateOfStatus,
    certifiedCopy,
    additionalSeriesFee,
    estimatedTotal: articlesOfOrganization + registeredAgentDesignation + certificateOfStatus + certifiedCopy + additionalSeriesFee
  };
}
function hasProtectedSeriesPhrase(name) {
  return /protected\s+series/i.test(name) || /(^|\s)p\.?s\.?(\s|$)/i.test(name);
}

