// server/db.ts
var db = null;
var migrated = false;
async function createDb() {
  if (env.DATABASE_URL) {
    const { neon } = await Promise.resolve().then(() => (init_serverless(), serverless_exports));
    const sql = neon(env.DATABASE_URL);
    return {
      async query(text, params = []) {
        const rows = await sql.query(text, params);
        return rows;
      }
    };
  }
  if (env.isProd) {
    throw new Error("DATABASE_URL is not set \u2014 the database is required in production.");
  }
  const { PGlite } = await import("@electric-sql/pglite");
  const { fileURLToPath } = await import("node:url");
  const { mkdirSync } = await import("node:fs");
  const dir = fileURLToPath(new URL("../.dev-data/pg", import.meta.url));
  mkdirSync(dir, { recursive: true });
  const pg = new PGlite(dir);
  return {
    async query(text, params = []) {
      const res = await pg.query(text, params);
      return res.rows;
    }
  };
}
